/**
 * Azure Functions with HTTP Trigger.
 */
public class Function {
    /**
     * This function will be invoked when a request is sent to the http url.
     * Only this path will be allowed, because it is defined in the function.json file.
     * @return A response to the request
     */
    public HttpResponseMessage run(
        @HttpTrigger(
            name = "req",
            authLevel = AuthorizationLevel.ANONYMOUS,
            methods = {HttpMethod.POST, HttpMethod.GET}
        ) HttpRequestMessage<Optional<String>> request,
        final ExecutionContext context
    ) {
        context.getLogger().info("Java HTTP trigger function processed a request.");

        // Parse query parameter
        final String query = request.getQueryParameters().get("name");
        final String name = request.getBody().orElse(query);

        if (name == null) {
            return request.createResponseBuilder(HttpStatus.BAD_REQUEST).body("Please pass a name on the query string or in the request body").build();
        } else {
            return request.createResponseBuilder(HttpStatus.OK).body("Hello, " + name).build();
        }
    }
}
